export const EXERCISE_BY_ID = Object.fromEntries(EXERCISES.map((e) => [e.id, e]));

export function getExercise(id) {
  return EXERCISE_BY_ID[id];
}

// Suchlink zu Technik-Videos (öffnet extern).
export function videoSearchUrl(ex) {
  return `https://www.youtube.com/results?search_query=${encodeURIComponent(`${ex.en} technique`)}`;
}
